// Title: Create SMIL stroke‑dashoffset animation for chart paths in an SVG exported from Aspose.Cells using C#
// Common Searches: how to add SMIL animation to SVG paths generated by Aspose.Cells chart in C# | inject <animate> element into worksheet SVG with Aspose.Cells .NET API | C# code to animate column chart SVG using stroke-dasharray and stroke-dashoffset | modify exported SVG from Aspose.Cells to include drawing animation | Aspose.Cells render worksheet to SVG and apply SMIL animation to paths
// Tags: SMIL animation with Aspose.Cells SVG | stroke-dashoffset animation for chart paths | export worksheet to SVG using SvgImageOptions | XDocument manipulation of Aspose.Cells SVG | C# animated SVG generation from Excel chart

using System;
using System.IO;
using System.Xml.Linq;
using Aspose.Cells;
using Aspose.Cells.Charts;
using Aspose.Cells.Rendering;

namespace SvgAnimationDemo
{
    // The example creates a workbook with a column chart, renders the worksheet to SVG via Aspose.Cells, loads the SVG into an XDocument, adds stroke‑dasharray and a SMIL <animate> element to each <path> to produce a drawing effect, and saves the animated SVG file.
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // 1. Create a sample workbook with a chart (charts generate SVG <path> elements)
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // Populate some data for the chart
                sheet.Cells["A1"].PutValue("Category");
                sheet.Cells["B1"].PutValue("Value");
                sheet.Cells["A2"].PutValue("Jan");
                sheet.Cells["B2"].PutValue(30);
                sheet.Cells["A3"].PutValue("Feb");
                sheet.Cells["B3"].PutValue(45);
                sheet.Cells["A4"].PutValue("Mar");
                sheet.Cells["B4"].PutValue(25);

                // Add a simple column chart
                int chartIndex = sheet.Charts.Add(ChartType.Column, 6, 0, 20, 8);
                Chart chart = sheet.Charts[chartIndex];
                chart.NSeries.Add("B2:B4", true);
                chart.NSeries.CategoryData = "A2:A4";

                // 2. Export the worksheet to SVG using SvgImageOptions (preferred)
                SvgImageOptions svgOptions = new SvgImageOptions
                {
                    OnePagePerSheet = true,   // Render each sheet as a single SVG page
                    FitToViewPort = true      // Make the SVG fit the viewport
                };

                // Render the sheet to a memory stream
                using (MemoryStream svgStream = new MemoryStream())
                {
                    try
                    {
                        SheetRender renderer = new SheetRender(sheet, svgOptions);
                        renderer.ToImage(0, svgStream);
                        svgStream.Position = 0;
                    }
                    catch (Exception renderEx)
                    {
                        Console.WriteLine("Error during SVG rendering: " + renderEx.Message);
                        return;
                    }

                    // 3. Load the SVG content into an XDocument for manipulation
                    XDocument svgDoc;
                    try
                    {
                        svgDoc = XDocument.Load(svgStream);
                    }
                    catch (Exception loadEx)
                    {
                        Console.WriteLine("Error loading SVG into XDocument: " + loadEx.Message);
                        return;
                    }

                    // Define the SVG namespace (most Aspose SVGs use the default namespace)
                    XNamespace svgNs = "http://www.w3.org/2000/svg";

                    // 4. Find all <path> elements and inject SMIL animation
                    foreach (XElement pathElem in svgDoc.Descendants(svgNs + "path"))
                    {
                        // Ensure the path has a stroke defined; if not, add a default stroke
                        if (pathElem.Attribute("stroke") == null)
                        {
                            pathElem.SetAttributeValue("stroke", "black");
                        }

                        // Add stroke-dasharray and stroke-dashoffset to enable "drawing" animation
                        string pathLength = pathElem.Attribute("stroke-dasharray")?.Value ?? "1000";
                        pathElem.SetAttributeValue("stroke-dasharray", pathLength);
                        pathElem.SetAttributeValue("stroke-dashoffset", pathLength);

                        // Create the <animate> element
                        XElement animateElem = new XElement(svgNs + "animate",
                            new XAttribute("attributeName", "stroke-dashoffset"),
                            new XAttribute("from", pathLength),
                            new XAttribute("to", "0"),
                            new XAttribute("dur", "4s"),
                            new XAttribute("repeatCount", "indefinite")
                        );

                        // Append the animation as a child of the <path>
                        pathElem.Add(animateElem);
                    }

                    // 5. Save the modified SVG to a file
                    string outputPath = Path.Combine(Directory.GetCurrentDirectory(), "AnimatedWorksheet.svg");
                    try
                    {
                        using (FileStream fileOut = new FileStream(outputPath, FileMode.Create, FileAccess.Write))
                        {
                            svgDoc.Save(fileOut);
                        }
                        Console.WriteLine($"Animated SVG saved to: {outputPath}");
                    }
                    catch (Exception saveEx)
                    {
                        Console.WriteLine("Error saving animated SVG: " + saveEx.Message);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("An unexpected error occurred while generating the animated SVG:");
                Console.WriteLine(ex.Message);
            }
        }
    }
}
